public class DeadlockPreventionExample {
    private final Object lock1 = new Object();
    private final Object lock2 = new Object();

    public void safeExecution() {
        // Always acquire locks in a consistent global order to prevent deadlocks
        synchronized (lock1) {
            synchronized (lock2) {
                // Critical section safely executing with ordered locks
                System.out.println(Thread.currentThread().getName() + " acquired both locks.");
            }
        }
    }
}
